.btn:hover { transform: translateY(-2px); border-color: var(--border-strong); background: var(--surface-strong); }
.btn.primary { color: oklch(11% 0.025 160); border-color: transparent; background: linear-gradient(135deg, var(--green), var(--cyan)); font-weight: 760; }
.btn.ghost { background: transparent; }

.panel, .card, .doc-card, .codebox, .accordion-item, .resource, .sidebar {
  border: 1px solid var(--border);
  background: linear-gradient(180deg, var(--surface), var(--surface-soft));
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}
.hero-terminal { border-radius: var(--radius); padding: 18px; transform: rotate(1deg); }
.terminal-top { display: flex; gap: 7px; margin-bottom: 16px; }
.dot { width: 11px; height: 11px; border-radius: 50%; background: var(--red); }
.dot:nth-child(2){ background: var(--amber); } .dot:nth-child(3){ background: var(--green); }
pre { margin: 0; white-space: pre-wrap; font: 14px/1.75 var(--mono); }
.codebox { border-radius: 18px; background: oklch(10% 0.026 255 / .88); color: oklch(94% 0.015 255); overflow: hidden; box-shadow: none; }
.codebox pre { padding: 18px; }
.code-line { color: var(--green); }
.token-comment { color: oklch(62% 0.04 255); }
.token-cmd { color: var(--cyan); }

.section { padding: 58px 0; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 22px; margin-bottom: 24px; }
.section-head p { max-width: 680px; margin-top: 12px; }
.grid { display: grid; gap: 16px; }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.card, .doc-card, .resource { border-radius: var(--radius); padding: 24px; position: relative; overflow: hidden; }
.card::after { content: ""; position: absolute; inset: auto 18px 0 18px; height: 1px; background: linear-gradient(90deg, transparent, var(--accent, var(--cyan)), transparent); opacity: .65; }
.card-icon { width: 42px; height: 42px; border-radius: 14px; display: grid; place-items: center; margin-bottom: 18px; background: color-mix(in oklch, var(--accent, var(--cyan)) 24%, transparent); color: var(--accent, var(--cyan)); font-family: var(--mono); font-weight: 900; }
.card h3, .doc-card h3, .resource h3 { margin-bottom: 10px; }
.card p, .doc-card p, .resource p { margin-bottom: 18px; }
.link { color: var(--green); font-weight: 730; }
.link:hover { color: var(--cyan); }

.cli-shell { display: grid; grid-template-columns: .9fr 1.1fr; gap: 18px; align-items: start; }
.accordion { display: grid; gap: 12px; }
.accordion-item { border-radius: 20px; overflow: hidden; box-shadow: none; }
.accordion-trigger { width: 100%; border: 0; background: transparent; color: var(--text); padding: 18px; display: flex; align-items: center; justify-content: space-between; cursor: pointer; text-align: left; }
.accordion-trigger strong { font-size: 17px; }
.accordion-trigger span { color: var(--muted); font-family: var(--mono); transition: transform .22s ease; }
.accordion-item.open .accordion-trigger span { transform: rotate(45deg); color: var(--green); }
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height .28s ease; }
.accordion-item.open .accordion-panel { max-height: 460px; }
.accordion-panel-inner { padding: 0 18px 18px; }
.steps { margin: 0; padding-left: 22px; color: var(--muted); }
.steps li { margin: 8px 0; }
.cli-preview { position: sticky; top: 92px; }
.tabs { display: flex; gap: 6px; padding: 10px; border-bottom: 1px solid var(--border); background: oklch(15% 0.03 255); }
.tab { border: 1px solid transparent; border-radius: 999px; padding: 7px 12px; cursor: pointer; color: var(--muted); background: transparent; font-family: var(--mono); }
.tab.active { background: oklch(25% 0.06 205); color: var(--cyan); border-color: oklch(62% 0.12 205 / .45); }
.code-caption { padding: 13px 18px 0; color: var(--faint); font: 12px/1 var(--mono); text-transform: uppercase; letter-spacing: .08em; }

.launch-band { border-radius: 32px; padding: 28px; background: linear-gradient(135deg, oklch(22% 0.08 250 / .88), oklch(18% 0.07 155 / .72)); border: 1px solid var(--border-strong); box-shadow: var(--shadow); }
.footer { margin-top: 48px; padding: 42px 0; border-top: 1px solid var(--border); }
.footer-grid { display: grid; grid-template-columns: 1.2fr repeat(4, 1fr); gap: 26px; }
.footer h4 { margin: 0 0 10px; }
.footer a { display: block; color: var(--muted); margin: 7px 0; }
.footer a:hover { color: var(--green); }

.docs-layout { display: grid; grid-template-columns: 286px minmax(0, 1fr); gap: 30px; align-items: start; padding-top: 28px; }
.sidebar { position: sticky; top: 92px; border-radius: 22px; padding: 14px; transition: width .25s ease, padding .25s ease; box-shadow: none; }
.sidebar-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 4px 4px 10px; border-bottom: 1px solid var(--border); margin-bottom: 10px; }
.sidebar-title { font-weight: 760; }
.sidebar-toggle { border-color: var(--border); padding: 7px 10px; }
.sidebar nav a { display: flex; align-items: center; gap: 10px; color: var(--muted); padding: 10px; border-radius: 12px; }
.sidebar nav a:hover, .sidebar nav a.active { color: var(--text); background: var(--surface-strong); }
.sidebar-code { margin-top: 12px; border-radius: 16px; }
.docs-layout.collapsed { grid-template-columns: 78px minmax(0, 1fr); }
.docs-layout.collapsed .sidebar { padding: 10px; }
.docs-layout.collapsed .sidebar-title, .docs-layout.collapsed .sidebar nav span, .docs-layout.collapsed .sidebar-code { display: none; }
.docs-layout.collapsed .sidebar nav a { justify-content: center; font-family: var(--mono); color: var(--green); }
.doc-main { min-width: 0; }
.doc-hero { padding: 42px 0 28px; }
.doc-section { padding: 34px 0; scroll-margin-top: 95px; }
.doc-section > p { max-width: 790px; margin-top: 12px; margin-bottom: 20px; }
.doc-card { box-shadow: none; min-height: 174px; }
.badge { display: inline-flex; align-items: center; border: 1px solid var(--border); background: var(--surface); color: var(--cyan); border-radius: 999px; padding: 5px 9px; font: 12px/1 var(--mono); margin-bottom: 12px; }
.actor-diagram { display: grid; grid-template-columns: repeat(4,1fr); gap: 14px; align-items: center; margin-top: 22px; }
.actor { border-radius: 22px; border: 1px solid var(--border-strong); padding: 20px; text-align: center; background: radial-gradient(circle at top, color-mix(in oklch, var(--accent, var(--cyan)) 22%, transparent), var(--surface)); }
.actor strong { display: block; font: 800 24px/1 var(--mono); color: var(--accent, var(--cyan)); margin-bottom: 8px; }
.status { color: var(--amber); border-color: oklch(78% 0.13 82 / .45); }

@media (max-width: 920px) {
  .mobile-menu { display: inline-flex; margin-left: auto; }
  .nav-links { position: fixed; inset: 72px 16px auto 16px; display: none; flex-direction: column; align-items: stretch; padding: 14px; border: 1px solid var(--border); background: var(--surface-strong); border-radius: 20px; box-shadow: var(--shadow); }
